const {test}=require('node:test'),assert=require('node:assert/strict');
const {DatabaseSync}=require('node:sqlite');
const E=require('../economy');
const admin={uid:'admin',email:'admin@centralfreefire.com.br'},user={uid:'person',provider:'google.com',email:'person@example.test'},base=Date.parse('2026-10-13T15:00:00-03:00');
function setup(){const sqlite=new DatabaseSync(':memory:'),sql={exec(query,...args){let result=[];for(const q of query.split(';').map(x=>x.trim()).filter(Boolean)){const s=sqlite.prepare(q);result=s.columns().length?s.all(...args):(s.run(...args),[]);}return result;}};E.initEconomy(sql);const data={'userAccounts/person/profile':{name:'Pessoa',username:'pessoa',gender:'masculino',createdAt:base},'userAccounts/friend/profile':{name:'Amigo',username:'amigo',gender:'feminino',createdAt:base},'userAccounts/admin/profile':{name:'Admin',username:'admin',gender:'masculino',createdAt:base},'communityProfileCatalog/asset-1':{title:'Exclusivo',kind:'frame',enabled:true,accessRule:'manual'}};const db={accountCreatedAt:async uid=>data['auth/'+uid+'/createdAt']??data['userAccounts/'+uid+'/profile']?.createdAt,get:async p=>structuredClone(data[p]??null),transact:async(p,f)=>{data[p]=f(structuredClone(data[p]??null));return data[p];},update:async changes=>Object.assign(data,changes)};let time=base,ticket=.1;const transaction=fn=>{sqlite.exec('BEGIN');try{const v=fn();sqlite.exec('COMMIT');return v;}catch(e){sqlite.exec('ROLLBACK');throw e;}};const core=E.createEconomy({sql,transaction,db,now:()=>time,random:()=>ticket,verifySession:async session=>({status:'verified',username:session})});return{core,data,sql,db,setTime:t=>time=t,setTicket:t=>ticket=t};}
test('daily boundaries use Brasilia and the probability table is exact',()=>{assert.equal(E.dayKey(Date.parse('2026-10-14T02:59:59Z')),'2026-10-13');assert.equal(E.dayKey(Date.parse('2026-10-14T03:00:00Z')),'2026-10-14');assert.equal(E.weekKey('2026-10-18'),'2026-10-12');const totals={};for(let i=0;i<10000;i++){const p=E.drawPrize(E.DEFAULT_CHANCES,i);totals[p.id]=(totals[p.id]||0)+1;}assert.deepEqual(totals,{p1:8000,p3:1000,p10:500,p25:300,p50:100,code:100});});
test('header wallet reads one indexed row with no synchronization, Firebase access, inserts or user override',async()=>{
 const s=setup(),calls=[];s.sql.exec('INSERT INTO eco_wallet(uid,balance,earned,spent) VALUES(?,?,?,?)',user.uid,1234,1500,266);
 const exec=s.sql.exec;s.sql.exec=(query,...args)=>{calls.push({query,args});return exec(query,...args);};s.db.get=async()=>{throw Error('Header must not access Firebase');};
 const before=s.sql.exec('SELECT total_changes() AS n')[0].n;calls.length=0;
 const result=await s.core.handle(user,{operation:'wallet',targetUid:'friend'});assert.deepEqual(JSON.parse(JSON.stringify(result)),{ok:true,currency:'CFF COINS',wallet:{balance:1234}});assert.equal(calls.length,1);assert.equal(calls[0].query,'SELECT balance FROM eco_wallet WHERE uid=?');assert.deepEqual(calls[0].args,[user.uid]);
 assert.equal(s.sql.exec('SELECT total_changes() AS n')[0].n,before);
 const empty=await s.core.handle({uid:'unknown',provider:'google.com'},{operation:'wallet'});assert.deepEqual(empty.wallet,{balance:0});assert.equal(s.sql.exec('SELECT COUNT(*) AS n FROM eco_wallet WHERE uid=?','unknown')[0].n,0);
 await assert.rejects(s.core.handle({uid:'person',provider:'anonymous'},{operation:'wallet'}),{status:403});await assert.rejects(s.core.handle({}, {operation:'wallet'}),{status:401});
 const status=await s.core.handle(user,{operation:'profileCheckinStatus'});assert.equal(status.wallet.balance,1234);
});
test('one daily spin and checkin remain idempotent across repeated requests',async()=>{const s=setup();await Promise.all([s.core.handle(user,{operation:'spin'}),s.core.handle(user,{operation:'spin'})]);await Promise.all([s.core.handle(user,{operation:'checkin'}),s.core.handle(user,{operation:'checkin'})]);const state=await s.core.state(user);assert.equal(state.wallet.balance,2);assert.equal(state.ledger.length,2);assert.equal(state.weekDays,1);});
test('voucher chance remains configured when code stock is empty',async()=>{const s=setup();const state=await s.core.state(user);assert.equal(state.chances.find(p=>p.id==='code').chance,1);assert.equal(state.chances.find(p=>p.id==='p1').chance,80);});
test('a winning voucher is delivered once without reserving or revealing a code',async()=>{const s=setup();await s.core.adminHandle(admin,{operation:'addStock',code:'TESTCODE1234',title:'Prêmio',bucket:'both'});s.setTicket(.995);const first=await s.core.handle(user,{operation:'spin'});assert.equal(first.result.id,'voucher');const again=await s.core.handle(user,{operation:'spin'});assert.equal(first.voucherId,again.voucherId);assert.equal(s.sql.exec('SELECT COUNT(*) AS n FROM eco_vouchers')[0].n,1);assert.equal(s.sql.exec('SELECT COUNT(*) AS n FROM eco_stock WHERE receipt IS NULL')[0].n,1);assert.equal(Object.keys(s.data).filter(p=>p.startsWith('communityCodeGifts/person/')).length,0);assert.equal((await s.core.state(user)).vouchers.availableCount,1);assert.equal((await s.core.state(user)).wallet.balance,0);assert.equal((await s.core.state(user)).pending.length,0);});
async function seedLegacySpin(s){const stock=s.sql.exec('SELECT * FROM eco_stock WHERE receipt IS NULL ORDER BY rowid LIMIT 1')[0],day=(await s.core.state(user)).day,id=crypto.randomUUID(),giftId='codegift-'+crypto.randomUUID(),result={id:'code',points:0,label:stock.title,imageUrl:stock.image||'/edition/gift.webp'},data={result,giftId,message:'Prêmio da roleta diária da Central!',stockHash:stock.hash};s.sql.exec('INSERT INTO eco_receipts VALUES(?,?,?,?,?,?,?,?)',id,user.uid,'spin:'+user.uid+':'+day,base,'spin','',JSON.stringify(data),'pending');s.sql.exec('UPDATE eco_stock SET receipt=? WHERE hash=?',id,stock.hash);s.sql.exec('INSERT OR REPLACE INTO eco_daily(uid,day,spin) VALUES(?,?,?)',user.uid,day,JSON.stringify({result,receiptId:id}));return {id,giftId,result};}

test('failed delivery can be retried without another spin or losing the reserved code',async()=>{const s=setup();await s.core.adminHandle(admin,{operation:'addStock',code:'TESTCODE1234',title:'Prêmio',bucket:'both'});const original=s.db.transact;let fail=true;s.db.transact=async(p,f)=>{if(fail&&p.startsWith('communityCodeGifts/')){fail=false;throw Error('offline');}return original(p,f);};await seedLegacySpin(s);s.setTicket(.995);await assert.rejects(s.core.handle(user,{operation:'spin'}));const state=await s.core.state(user);assert.equal(state.pending.length,1);const reservedHash=s.sql.exec('SELECT hash FROM eco_stock')[0].hash;assert.equal((await s.core.adminHandle(admin,{operation:'stockStatus',hashes:[reservedHash]})).stock[0].status,'pending');await assert.rejects(s.core.adminHandle(admin,{operation:'moveStock',hash:reservedHash,bucket:'shop'}),{status:409});await s.core.handle(user,{operation:'retryDelivery',receiptId:state.pending[0].id});assert.equal((await s.core.state(user)).pending.length,0);});
test('insufficient balance and exhausted stock cannot spend points',async()=>{const s=setup();await assert.rejects(s.core.handle(user,{operation:'redeem',itemId:'code-default',nonce:crypto.randomUUID()}));assert.equal((await s.core.state(user)).wallet.balance,0);await s.core.adminHandle(admin,{operation:'adjust',targetUid:'person',delta:1000,reason:'Teste',nonce:crypto.randomUUID()});await assert.rejects(s.core.handle(user,{operation:'redeem',itemId:'code-default',nonce:crypto.randomUUID()}));assert.equal((await s.core.state(user)).wallet.balance,1000);});
test('redemption debits once, delivers to the existing inventory and blocks repeat cosmetic purchases',async()=>{const s=setup();await s.core.adminHandle(admin,{operation:'saveItem',item:{id:'frame',kind:'frame',assetId:'asset-1',title:'Moldura',price:80,enabled:true}});await s.core.adminHandle(admin,{operation:'adjust',targetUid:'person',delta:100,reason:'Teste',nonce:crypto.randomUUID()});await s.core.handle(user,{operation:'redeem',itemId:'frame',nonce:crypto.randomUUID()});assert.equal((await s.core.state(user)).wallet.balance,20);assert(s.data['communityImageOwnership/person/asset-1']);await assert.rejects(s.core.handle(user,{operation:'redeem',itemId:'frame',nonce:crypto.randomUUID()}));assert.equal((await s.core.state(user)).wallet.balance,20);});
test('a referral requires three distinct activity days and a verified Instagram',async()=>{const s=setup(),ref=(await s.core.state(user)).inviteCode,friend={uid:'friend',provider:'google.com'};await s.core.handle(friend,{operation:'attachReferral',code:ref});for(let day=0;day<3;day++){s.setTime(base+day*86400000);await s.core.handle(friend,{operation:'checkin'});}assert.equal((await s.core.state(user)).wallet.balance,0);s.data['communityInstagramLinks/friend']={username:'verified'};s.data['userAccounts/friend/community']={session:'verified'};await s.core.handle(friend,{operation:'checkin'});await s.core.handle(friend,{operation:'checkin'});assert.equal((await s.core.state(user)).wallet.balance,5);});
test('self referrals and old accounts do not earn invitation points',async()=>{const s=setup(),code=(await s.core.state(user)).inviteCode;assert.equal((await s.core.handle(user,{operation:'attachReferral',code})).attached,false);s.data['userAccounts/friend/profile'].createdAt=base-2*86400000;assert.equal((await s.core.handle({uid:'friend',provider:'google.com'},{operation:'attachReferral',code})).attached,false);});
test('five active days add a single weekly bonus and signup is also once-only',async()=>{const s=setup();for(let d=0;d<6;d++){s.setTime(base+d*86400000);await s.core.handle(user,{operation:'checkin'});}assert.equal((await s.core.state(user)).wallet.balance,9);s.data['communityInstagramLinks/person']={username:'verified'};s.data['userAccounts/person/community']={session:'verified'};await s.core.handle(user,{operation:'signup'});await s.core.handle(user,{operation:'signup'});assert.equal((await s.core.state(user)).wallet.balance,12);});
test('regular users and cosmetic administrator badges cannot manage points or stock',async()=>{const s=setup();for(const op of ['dashboard','addStock','adjust','saveChances'])await assert.rejects(s.core.adminHandle({...user,administrator:true},{operation:op}),{status:403});await assert.rejects(s.core.handle({},{operation:'state'}),{status:401});await assert.rejects(s.core.adminHandle(admin,{operation:'adjust',targetUid:'person',delta:-1,reason:'Teste',nonce:crypto.randomUUID()}));assert.equal((await s.core.state(user)).wallet.balance,0);});
test('another account cannot retrieve a pending prize receipt',async()=>{const s=setup();await s.core.adminHandle(admin,{operation:'addStock',code:'TESTCODE1234',title:'Prêmio',bucket:'both'});const original=s.db.transact;s.db.transact=async(p,f)=>{if(p.startsWith('communityCodeGifts/'))throw Error('offline');return original(p,f);};await seedLegacySpin(s);s.setTicket(.995);await assert.rejects(s.core.handle(user,{operation:'spin'}));const state=await s.core.state(user);await assert.rejects(s.core.handle({uid:'friend',provider:'google.com'},{operation:'retryDelivery',receiptId:state.pending[0].id}),{status:404});});
test('a lost cosmetic redemption response is retried with the same receipt and one debit',async()=>{const s=setup();await s.core.adminHandle(admin,{operation:'saveItem',item:{id:'frame',kind:'frame',assetId:'asset-1',title:'Moldura',price:80,enabled:true}});await s.core.adminHandle(admin,{operation:'adjust',targetUid:'person',delta:100,reason:'Teste',nonce:crypto.randomUUID()});const request={operation:'redeem',itemId:'frame',nonce:crypto.randomUUID()};await Promise.all([s.core.handle(user,request),s.core.handle(user,request)]);await s.core.handle(user,request);assert.equal((await s.core.state(user)).wallet.balance,20);assert.equal(Object.keys(s.data).filter(p=>p.startsWith('communityGifts/person/')).length,1);});
test('concurrent players can each win one voucher without claiming stock or changing configured odds',async()=>{const s=setup();await s.core.adminHandle(admin,{operation:'addStock',code:'TESTCODE1234',title:'Prêmio',bucket:'roulette'});s.setTicket(.995);const results=await Promise.all([s.core.handle(user,{operation:'spin'}),s.core.handle({uid:'friend',provider:'google.com'},{operation:'spin'})]);assert.equal(results.filter(r=>r.result.id==='voucher').length,2);assert.notEqual(results[0].voucherId,results[1].voucherId);assert.equal(Object.keys(s.data).filter(p=>p.startsWith('communityCodeGifts/')).length,0);assert.equal(s.sql.exec('SELECT COUNT(*) AS n FROM eco_stock WHERE receipt IS NULL')[0].n,1);assert.equal((await s.core.state(user)).chances.find(p=>p.id==='code').chance,1);});
test('code shop retries debit once and the thirty-day limit rejects a new purchase',async()=>{const s=setup();for(let i=0;i<2;i++)await s.core.adminHandle(admin,{operation:'addStock',code:'TESTCODE123'+i,title:'Prêmio',bucket:'shop'});await s.core.adminHandle(admin,{operation:'adjust',targetUid:'person',delta:2000,reason:'Teste',nonce:crypto.randomUUID()});const request={operation:'redeem',itemId:'code-default',nonce:crypto.randomUUID()};await s.core.handle(user,request);await s.core.handle(user,request);assert.equal((await s.core.state(user)).wallet.balance,1000);await assert.rejects(s.core.handle(user,{...request,nonce:crypto.randomUUID()}),/30 dias/);s.setTime(base+30*86400000);await s.core.handle(user,{...request,nonce:crypto.randomUUID()});assert.equal((await s.core.state(user)).wallet.balance,0);});
test('old Firebase Auth creation dates cannot be forged through a recent profile date',async()=>{const s=setup(),code=(await s.core.state(user)).inviteCode;s.data['auth/friend/createdAt']=base-2*86400000;assert.equal((await s.core.handle({uid:'friend',provider:'google.com'},{operation:'attachReferral',code})).attached,false);});
test('referrals reward at most five unique verified Instagram users per month',async()=>{const s=setup(),code=(await s.core.state(user)).inviteCode;for(let i=0;i<7;i++){const uid='ref-'+i,ig=i===6?'instagram0':'instagram'+i;s.data['userAccounts/'+uid+'/profile']={name:'Amigo',username:'amigo'+i,gender:'masculino',createdAt:base};s.data['userAccounts/'+uid+'/community']={session:ig};s.data['communityInstagramLinks/'+uid]={username:ig};s.setTime(base);await s.core.handle({uid,provider:'google.com'},{operation:'attachReferral',code});for(let d=0;d<3;d++){s.setTime(base+d*86400000);await s.core.handle({uid,provider:'google.com'},{operation:'checkin'});}}const state=await s.core.state(user);assert.equal(state.wallet.balance,25);assert.equal(state.paidInvitesThisMonth,5);assert.equal(state.referrals.find(r=>r.status==='capped').n,1);assert.equal(state.referrals.find(r=>r.status==='duplicate').n,1);});
test('wallet requests cannot select a different user or write ranking points',async()=>{const s=setup();s.data['ranking/test']={points:300};const initial=structuredClone(s.data);await s.core.handle(user,{operation:'checkin',targetUid:'friend',points:999999});assert.equal((await s.core.state(user)).wallet.balance,1);assert.equal((await s.core.state({uid:'friend',provider:'google.com'})).wallet.balance,0);assert.deepEqual(s.data,initial);await assert.rejects(s.core.adminHandle(user,{operation:'memberWallet',targetUid:'friend'}),{status:403});});
test('free or administrator-only assets and malformed chance tables cannot be sold',async()=>{const s=setup(),item={id:'frame',kind:'frame',assetId:'asset-1',title:'Moldura',price:80,enabled:true};await s.core.adminHandle(admin,{operation:'saveItem',item});s.data['communityProfileCatalog/asset-1'].accessRule='all';await s.core.adminHandle(admin,{operation:'adjust',targetUid:'person',delta:100,reason:'Teste',nonce:crypto.randomUUID()});await assert.rejects(s.core.handle(user,{operation:'redeem',itemId:'frame',nonce:crypto.randomUUID()}));assert.equal((await s.core.state(user)).wallet.balance,100);await assert.rejects(s.core.adminHandle(admin,{operation:'saveItem',item}));await assert.rejects(s.core.adminHandle(admin,{operation:'saveChances',chances:E.DEFAULT_CHANCES.map(p=>({...p,chance:50}))}));});
