test('a reserved stock code cannot also be sent as a manual gift',async()=>{const s=setup(),b={operation:'addStock',code:'TESTCODE1234',title:'Prêmio',bucket:'both'};await s.core.adminHandle(admin,b);assert.equal((await s.core.adminHandle(admin,b)).duplicate,true);const gifts=require('../code-gifts');await assert.rejects(gifts.sendCodeGift(s.db,admin,{targetUid:user.uid,expectedUsername:'pessoa',title:'Prêmio',code:b.code,requestId:crypto.randomUUID()}),{status:409});});
test('existing SQLite wallets, codes and daily results survive the six-prize migration',async()=>{const s=setup();s.sql.exec('ALTER TABLE eco_stock DROP COLUMN image');s.sql.exec('INSERT INTO eco_stock VALUES(?,?,?,?,?,NULL)','a'.repeat(64),'MIGRATION123','Prêmio antigo',0,'both');s.sql.exec('DELETE FROM eco_settings WHERE id=?','chances-v2');s.sql.exec('UPDATE eco_settings SET data=? WHERE id=?',JSON.stringify([{id:'p1',points:1,chance:85},{id:'p3',points:3,chance:10},{id:'p10',points:10,chance:2},{id:'p50',points:50,chance:2},{id:'code',points:0,chance:1}]),'chances');await s.core.handle(user,{operation:'checkin'});const spin=JSON.stringify({result:{id:'p1',points:1,label:'1 ponto'}});s.sql.exec('UPDATE eco_daily SET spin=? WHERE uid=?',spin,user.uid);E.initEconomy(s.sql);const state=await s.core.state(user);assert.equal(state.wallet.balance,1);assert.equal(state.spin.result.id,'p1');assert.deepEqual(state.chances,E.DEFAULT_CHANCES);assert.equal(state.shop[0].title,'Prêmio antigo');assert.equal(state.shop[0].quantity,1);const custom=E.DEFAULT_CHANCES.map(p=>({...p,chance:p.id==='p1'?70:p.id==='p3'?20:p.chance}));await s.core.adminHandle(admin,{operation:'saveChances',chances:custom});E.initEconomy(s.sql);assert.deepEqual((await s.core.state(user)).chances,custom);});
test('the new 25-point prize is credited once and cannot exceed the fifty-point limit',async()=>{const s=setup();s.setTicket(.975);const result=await s.core.handle(user,{operation:'spin'});assert.equal(result.result.points,25);await s.core.handle(user,{operation:'spin'});assert.equal((await s.core.state(user)).wallet.balance,25);assert.equal(Math.max(...E.DEFAULT_CHANCES.map(p=>p.points)),50);});
test('the shop shows photos, prices and quantities per codiguinho without exposing codes',async()=>{const s=setup();for(const [code,title,imageUrl] of [['PRIVATECODE111','Calça','https://centralfreefire.com.br/items/pants.webp'],['PRIVATECODE222','Calça','https://centralfreefire.com.br/items/pants.webp'],['PRIVATECODE333','Camisa','https://centralfreefire.com.br/items/shirt.webp']])await s.core.adminHandle(admin,{operation:'addStock',code,title,imageUrl,bucket:'shop'});const state=await s.core.state(user);assert.equal(state.codeStock.shop,3);assert.equal(state.shop.length,2);assert.equal(state.shop.find(p=>p.title==='Calça').quantity,2);assert.equal(state.shop.find(p=>p.title==='Camisa').price,1000);assert.equal(state.shop.find(p=>p.title==='Calça').imageUrl,'https://centralfreefire.com.br/items/pants.webp');assert(!JSON.stringify(state).includes('PRIVATECODE'));assert(!JSON.stringify(state).includes('stockHash'));});
test('an exhausted selected prize cannot be replaced with another code or debit the wallet',async()=>{const s=setup();for(const [code,title] of [['CHOICECODE111','Calça'],['CHOICECODE222','Camisa']])await s.core.adminHandle(admin,{operation:'addStock',code,title,bucket:'shop'});for(const uid of ['person','friend'])await s.core.adminHandle(admin,{operation:'adjust',targetUid:uid,delta:1000,reason:'Teste',nonce:crypto.randomUUID()});const choice=(await s.core.state(user)).shop.find(p=>p.title==='Calça').codeChoice;await s.core.handle({uid:'friend',provider:'google.com'},{operation:'redeem',itemId:'code-default',codeChoice:choice,nonce:crypto.randomUUID()});await assert.rejects(s.core.handle(user,{operation:'redeem',itemId:'code-default',codeChoice:choice,nonce:crypto.randomUUID()}),{status:409});assert.equal((await s.core.state(user)).wallet.balance,1000);const next=(await s.core.state(user)).shop.find(p=>p.title==='Camisa').codeChoice;await s.core.handle(user,{operation:'redeem',itemId:'code-default',codeChoice:next,nonce:crypto.randomUUID()});const gift=Object.entries(s.data).find(([p])=>p.startsWith('communityCodeGifts/person/'))[1];assert.equal(gift.code,'CHOICECODE222');assert.equal((await s.core.state(user)).wallet.balance,0);assert.equal((await s.core.state(user)).codeRedeemAvailableAt,base+30*86400000);});
test('stock photos are stored once and served separately from private code data',async()=>{const s=setup(),photo='data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+/lZkAAAAASUVORK5CYII=';for(const code of ['PHOTOCODE111','PHOTOCODE222'])await s.core.adminHandle(admin,{operation:'addStock',code,title:'Foto',imageUrl:photo,bucket:'both'});assert.equal(s.sql.exec('SELECT COUNT(*) AS n FROM eco_media')[0].n,1);const row=(await s.core.state(user)).shop[0];assert(!JSON.stringify(row).includes('base64'));const id=row.imageUrl.split('/').pop(),media=require('../economy-media').read(s.sql,id);assert.equal(media.type,'image/png');assert.equal(require('../economy-media').read(s.sql,'not-a-media-id'),null);assert(!JSON.stringify(media).includes('PHOTOCODE'));await assert.rejects(s.core.adminHandle(admin,{operation:'addStock',code:'PHOTOFAIL111',title:'Foto',imageUrl:'data:image/svg+xml;base64,PHN2Zz4=',bucket:'shop'}),{status:400});await assert.rejects(s.core.adminHandle(admin,{operation:'updateStock',hash:(await s.core.adminHandle(admin,{operation:'dashboard'})).stock[0].hash,title:'Foto',imageUrl:'https://evil.example/track.png',bucket:'shop'}),{status:400});});
test('existing unused codes can receive photos without releasing or duplicating reservations',async()=>{const s=setup();for(const code of ['SYNCIMAGE111','SYNCIMAGE222'])await s.core.adminHandle(admin,{operation:'addStock',code,title:'Prêmio',bucket:'both'});assert.equal((await s.core.adminHandle(admin,{operation:'stockPhotos',codes:['SYNCIMAGE111','SYNCIMAGE222'],imageUrl:'https://centralfreefire.com.br/item.webp'})).updated,2);await s.core.adminHandle(admin,{operation:'adjust',targetUid:'person',delta:1000,reason:'Teste',nonce:crypto.randomUUID()});await s.core.handle(user,{operation:'redeem',itemId:'code-default',nonce:crypto.randomUUID()});assert.equal((await s.core.adminHandle(admin,{operation:'stockPhotos',codes:['SYNCIMAGE111','SYNCIMAGE222'],imageUrl:'https://centralfreefire.com.br/item-new.webp'})).updated,1);const reserved=s.sql.exec('SELECT hash FROM eco_stock WHERE receipt IS NOT NULL')[0].hash;await assert.rejects(s.core.adminHandle(admin,{operation:'updateStock',hash:reserved,title:'Alterado',bucket:'both',imageUrl:''}),{status:409});assert.equal(Object.keys(s.data).filter(p=>p.startsWith('communityCodeGifts/person/')).length,1);});

test('destination overlays read server stock including consumed codes and preserve photo and expiry on moves',async()=>{const s=setup(),code='DESTINATION111',expiresAt=base+86400000,imageUrl='https://centralfreefire.com.br/item.webp';await s.core.adminHandle(admin,{operation:'addStock',code,title:'Dino',bucket:'shop',imageUrl,expiresAt});const hash=(await s.core.adminHandle(admin,{operation:'dashboard'})).stock[0].hash;let found=await s.core.adminHandle(admin,{operation:'stockStatus',hashes:[hash,hash,'0'.repeat(64)]});assert.equal(found.stock.length,1);assert.equal(found.stock[0].status,'available');assert(!JSON.stringify(found).includes(code));await assert.rejects(s.core.adminHandle(user,{operation:'stockStatus',hashes:[hash]}),{status:403});await assert.rejects(s.core.adminHandle(user,{operation:'moveStock',hash,bucket:'both'}),{status:403});await s.core.adminHandle(admin,{operation:'moveStock',hash,bucket:'roulette'});let state=await s.core.state(user);assert.equal(state.codeStock.shop,1);assert.equal(state.codeStock.roulette,1);assert.equal(state.shop[0].imageUrl,imageUrl);assert.equal(state.shop[0].title,'Dino');assert(!JSON.stringify(state.shop).includes(code));found=(await s.core.adminHandle(admin,{operation:'stockStatus',hashes:[hash]})).stock[0];assert.equal(found.expires,expiresAt);assert.equal(found.image,imageUrl);await s.core.adminHandle(admin,{operation:'moveStock',hash,bucket:'both'});assert.equal((await s.core.state(user)).shop[0].imageUrl,imageUrl);s.setTicket(.995);const won=await s.core.handle(user,{operation:'spin'});await s.core.handle(user,{operation:'redeem',itemId:'code-default',payment:'voucher',voucherId:won.voucherId,codeChoice:(await s.core.state(user)).shop[0].codeChoice,nonce:crypto.randomUUID()});found=(await s.core.adminHandle(admin,{operation:'stockStatus',hashes:[hash]})).stock[0];assert.equal(found.status,'claimed');assert(!('receipt' in found));await assert.rejects(s.core.adminHandle(admin,{operation:'moveStock',hash,bucket:'shop'}),{status:409});assert.equal((await s.core.state(user)).codeStock.shop,0);});
test('expired stock cannot be moved or shown as a available roulette prize',async()=>{const s=setup();await s.core.adminHandle(admin,{operation:'addStock',code:'EXPIREDEST111',title:'Expira',bucket:'both',expiresAt:base+1000});const hash=(await s.core.adminHandle(admin,{operation:'dashboard'})).stock[0].hash;s.setTime(base+2000);assert.equal((await s.core.adminHandle(admin,{operation:'stockStatus',hashes:[hash]})).stock[0].status,'expired');await assert.rejects(s.core.adminHandle(admin,{operation:'moveStock',hash,bucket:'shop'}),{status:409});assert.equal((await s.core.state(user)).roulettePrizes.length,0);for(const hashes of [['bad'],new Array(501).fill(hash)])await assert.rejects(s.core.adminHandle(admin,{operation:'stockStatus',hashes}),{status:400});await assert.rejects(s.core.adminHandle(admin,{operation:'moveStock',hash,bucket:'manual'}),{status:400});});
test('CFF COINS ranking is private, distinguishes current balance from total earned, and never exposes codes',async()=>{const s=setup();await s.core.adminHandle(admin,{operation:'adjust',targetUid:'person',delta:2000,reason:'Teste',nonce:crypto.randomUUID()});await s.core.adminHandle(admin,{operation:'adjust',targetUid:'person',delta:-1800,reason:'Teste',nonce:crypto.randomUUID()});await s.core.adminHandle(admin,{operation:'adjust',targetUid:'friend',delta:500,reason:'Teste',nonce:crypto.randomUUID()});await s.core.adminHandle(admin,{operation:'addStock',code:'RANKSECRET111',title:'Segredo',bucket:'shop'});const balances=await s.core.adminHandle(admin,{operation:'coinRanking'}),earned=await s.core.adminHandle(admin,{operation:'coinRanking',sort:'earned'});assert.equal(balances.currency,'CFF COINS');assert.deepEqual(balances.entries.map(p=>p.uid),['friend','person']);assert.deepEqual(earned.entries.map(p=>p.uid),['person','friend']);assert.equal(earned.entries[0].name,'Pessoa');assert.equal(earned.entries[0].username,'pessoa');assert.deepEqual({...balances.totals},{participants:2,balance:700,earned:2500,spent:1800});assert(!JSON.stringify(balances).includes('RANKSECRET'));await assert.rejects(s.core.adminHandle(user,{operation:'coinRanking'}),{status:403});for(const body of [{sort:'drop table'},{offset:-1},{offset:1.5}])await assert.rejects(s.core.adminHandle(admin,{operation:'coinRanking',...body}),{status:400});assert.equal((await s.core.state(user)).wallet.balance,200);assert.equal((await s.core.state(user)).currency,'CFF COINS');});
test('coin ranking pagination is bounded and existing wallet profile names are cached',async()=>{const s=setup();for(let n=0;n<25;n++){const uid='wallet-'+String(n).padStart(2,'0');s.sql.exec('INSERT INTO eco_wallet VALUES(?,?,?,?)',uid,10,10,0);s.data['userAccounts/'+uid+'/profile']={name:'Pessoa '+n,username:'user_'+n};}let reads=0;const get=s.db.get;s.db.get=async path=>{reads++;return get(path);};let result=await s.core.adminHandle(admin,{operation:'coinRanking'});assert.equal(result.entries.length,20);assert.equal(result.total,25);assert(result.hasMore);assert.equal(reads,20);const first=result.entries.map(r=>r.uid);result=await s.core.adminHandle(admin,{operation:'coinRanking'});assert.equal(reads,20);result=await s.core.adminHandle(admin,{operation:'coinRanking',offset:20});assert.equal(result.entries.length,5);assert.equal(result.entries[0].position,21);assert(!result.hasMore);assert(result.entries.every(r=>!first.includes(r.uid)));assert.equal(reads,25);});

async function issueVoucher(s,{uid='person',username=uid==='person'?'pessoa':'amigo',expiresAt=base+86400000,nonce=crypto.randomUUID(),message='Obrigado!'}={}){return s.core.adminHandle(admin,{operation:'grantVoucher',targetUid:uid,expectedUsername:username,expiresAt,nonce,message});}
async function voucherChoice(s,code='VALECODE1234',title='Codiguinho escolhido'){await s.core.adminHandle(admin,{operation:'addStock',code,title,bucket:'shop'});return (await s.core.state(user)).shop.find(x=>x.title===title).codeChoice;}
test('vouchers resolve only the exact site username without downloading the user catalogue',async()=>{const s=setup();s.data['communityUsernames/pessoa']='person';const reads=[],get=s.db.get;s.db.get=async path=>{reads.push(path);return get(path);};const result=await s.core.adminHandle(admin,{operation:'findVoucherRecipient',username:' @Pessoa '});assert.equal(result.recipient.uid,'person');assert.deepEqual(reads,['communityUsernames/pessoa','userAccounts/person/profile']);await assert.rejects(s.core.adminHandle(admin,{operation:'findVoucherRecipient',username:'@missing'}),{status:404});s.data['userAccounts/person/profile'].username='renomeado';await assert.rejects(s.core.adminHandle(admin,{operation:'findVoucherRecipient',username:'@pessoa'}),{status:409});});
test('a voucher grant is idempotent even after expiry and binds recipient, expiration and message',async()=>{const s=setup(),nonce=crypto.randomUUID(),first=await issueVoucher(s,{nonce});assert.equal(first.voucher.status,'available');await issueVoucher(s,{nonce});assert.equal(s.sql.exec('SELECT COUNT(*) AS n FROM eco_vouchers')[0].n,1);await assert.rejects(issueVoucher(s,{nonce,message:'Outra mensagem'}),{status:409});await assert.rejects(issueVoucher(s,{nonce,uid:'friend'}),{status:409});s.setTime(base+2*86400000);assert.equal((await issueVoucher(s,{nonce})).duplicate,true);assert.equal((await s.core.state(user)).vouchers.availableCount,0);await assert.rejects(issueVoucher(s,{expiresAt:base}),{status:400});await assert.rejects(issueVoucher(s,{username:'mudou'}),{status:409});});
test('a voucher pays for the selected shop code with zero coins and no monthly cooldown',async()=>{const s=setup(),v=await issueVoucher(s),codeChoice=await voucherChoice(s);const request={operation:'redeem',payment:'voucher',itemId:'code-default',voucherId:v.voucher.id,codeChoice,nonce:crypto.randomUUID()};await Promise.all([s.core.handle(user,request),s.core.handle(user,request)]);await s.core.handle(user,request);const state=await s.core.state(user);assert.equal(state.wallet.balance,0);assert.equal(state.wallet.spent,0);assert.equal(state.codeRedeemAvailableAt,0);assert.equal(state.vouchers.availableCount,0);assert.equal(state.vouchers.entries[0].status,'used');assert.equal(state.vouchers.entries[0].prize,'Codiguinho escolhido');assert.equal(Object.keys(s.data).filter(p=>p.startsWith('communityCodeGifts/person/')).length,1);await assert.rejects(s.core.handle(user,{...request,nonce:crypto.randomUUID()}),{status:409});await assert.rejects(s.core.handle(user,{...request,payment:'coins'}),{status:409});});
test('coin cooldown and voucher redemptions are independent and separate vouchers work immediately',async()=>{const s=setup();await s.core.adminHandle(admin,{operation:'adjust',targetUid:'person',delta:2000,reason:'Teste',nonce:crypto.randomUUID()});const codeChoice=await voucherChoice(s);await s.core.handle(user,{operation:'redeem',itemId:'code-default',codeChoice,nonce:crypto.randomUUID()});for(let i=0;i<2;i++){const v=await issueVoucher(s),choice=await voucherChoice(s,'VALESECOND'+i);await s.core.handle(user,{operation:'redeem',payment:'voucher',voucherId:v.voucher.id,itemId:'code-default',codeChoice:choice,nonce:crypto.randomUUID()});}const state=await s.core.state(user);assert.equal(state.wallet.balance,1000);assert.equal(state.wallet.spent,1000);assert.equal(state.codeRedeemAvailableAt,base+30*86400000);assert.equal(state.vouchers.entries.filter(v=>v.status==='used').length,2);await assert.rejects(s.core.handle(user,{operation:'redeem',itemId:'code-default',nonce:crypto.randomUUID()}),/30 dias/);});
test('foreign, expired, cancelled or reused vouchers cannot reserve stock or debit coins',async()=>{const s=setup(),v=await issueVoucher(s),codeChoice=await voucherChoice(s),request={operation:'redeem',payment:'voucher',itemId:'code-default',voucherId:v.voucher.id,codeChoice,nonce:crypto.randomUUID()};await assert.rejects(s.core.handle({uid:'friend',provider:'google.com'},request),{status:409});assert.equal((await s.core.state({uid:'friend',provider:'google.com'})).vouchers.entries.length,0);assert.equal((await s.core.state(user)).codeStock.shop,1);s.setTime(base+86400000);await assert.rejects(s.core.handle(user,request),{status:409});assert.equal((await s.core.state(user)).vouchers.entries[0].status,'expired');s.setTime(base);await s.core.adminHandle(admin,{operation:'revokeVoucher',id:v.voucher.id,reason:'Enviado por engano'});await s.core.adminHandle(admin,{operation:'revokeVoucher',id:v.voucher.id,reason:'Repetição'});await assert.rejects(s.core.handle(user,request),{status:409});assert.equal((await s.core.state(user)).vouchers.entries[0].reason,'Enviado por engano');assert.equal((await s.core.state(user)).codeStock.shop,1);assert.equal(s.sql.exec('SELECT COUNT(*) AS n FROM eco_receipts')[0].n,0);});
test('unavailable or altered shop choices preserve the voucher and never substitute another code',async()=>{const s=setup(),v=await issueVoucher(s);await voucherChoice(s);const request={operation:'redeem',payment:'voucher',itemId:'code-default',voucherId:v.voucher.id,nonce:crypto.randomUUID()};await assert.rejects(s.core.handle(user,request),{status:400});await assert.rejects(s.core.handle(user,{...request,codeChoice:{title:'Não existe',imageUrl:''}}),{status:409});assert.equal((await s.core.state(user)).vouchers.availableCount,1);assert.equal((await s.core.state(user)).codeStock.shop,1);await s.core.adminHandle(admin,{operation:'saveItem',item:{id:'frame',kind:'frame',assetId:'asset-1',title:'Moldura',price:80,enabled:true}});await assert.rejects(s.core.handle(user,{...request,itemId:'frame'}),{status:400});await assert.rejects(s.core.handle(user,{...request,payment:'free'}),{status:400});});
test('concurrent purchases cannot spend one voucher twice or assign the final code to two people',async()=>{const s=setup(),one=await issueVoucher(s),two=await issueVoucher(s,{uid:'friend'}),codeChoice=await voucherChoice(s),request={operation:'redeem',payment:'voucher',itemId:'code-default',codeChoice};const results=await Promise.allSettled([s.core.handle(user,{...request,voucherId:one.voucher.id,nonce:crypto.randomUUID()}),s.core.handle({uid:'friend',provider:'google.com'},{...request,voucherId:two.voucher.id,nonce:crypto.randomUUID()})]);assert.equal(results.filter(x=>x.status==='fulfilled').length,1);assert.equal(s.sql.exec('SELECT COUNT(*) AS n FROM eco_vouchers WHERE receipt IS NULL')[0].n,1);await voucherChoice(s,'ANOTHER12345','Outro codiguinho');await assert.rejects(s.core.handle(user,{...request,voucherId:one.voucher.id,codeChoice:(await s.core.state(user)).shop[0].codeChoice,nonce:crypto.randomUUID()}),{status:409});assert.equal((await s.core.state(user)).codeStock.shop,1);});
test('a failed voucher delivery stays reserved and can finish after expiry without another voucher',async()=>{const s=setup(),v=await issueVoucher(s),codeChoice=await voucherChoice(s),request={operation:'redeem',payment:'voucher',itemId:'code-default',voucherId:v.voucher.id,codeChoice,nonce:crypto.randomUUID()},transact=s.db.transact;s.db.transact=async(p,f)=>{if(p.startsWith('communityCodeGifts/'))throw Error('offline');return transact(p,f);};await assert.rejects(s.core.handle(user,request),/offline/);let state=await s.core.state(user);assert.equal(state.vouchers.entries[0].status,'reserved');assert.equal(state.vouchers.availableCount,0);await assert.rejects(s.core.adminHandle(admin,{operation:'revokeVoucher',id:v.voucher.id,reason:'Não pode'}),{status:409});s.setTime(base+2*86400000);s.db.transact=transact;await s.core.handle(user,{operation:'retryDelivery',receiptId:state.pending[0].id});state=await s.core.state(user);assert.equal(state.pending.length,0);assert.equal(state.vouchers.entries[0].status,'used');assert.equal(state.wallet.spent,0);assert.equal(Object.keys(s.data).filter(p=>p.startsWith('communityCodeGifts/person/')).length,1);});
test('voucher history is private, paginated and preserves records and uploaded art across initialization',async()=>{const s=setup();for(let i=0;i<23;i++)await issueVoucher(s,{expiresAt:base+(i+1)*86400000});const imageUrl='https://centralfreefire.com.br/edition/vale.webp';await s.core.adminHandle(admin,{operation:'saveVoucherConfig',imageUrl});E.initEconomy(s.sql);const state=await s.core.state(user);assert.equal(state.vouchers.availableCount,23);assert.equal(state.vouchers.entries.length,20);assert.equal(state.vouchers.next.expiresAt,base+86400000);assert.equal(state.vouchers.config.imageUrl,imageUrl);let page=await s.core.adminHandle(admin,{operation:'listVouchers'});assert.equal(page.entries.length,20);assert.equal(page.total,23);assert.equal(page.hasMore,true);page=await s.core.adminHandle(admin,{operation:'listVouchers',offset:20,status:'available'});assert.equal(page.entries.length,3);assert.equal(page.hasMore,false);for(const operation of ['voucherConfig','saveVoucherConfig','findVoucherRecipient','grantVoucher','listVouchers','revokeVoucher'])await assert.rejects(s.core.adminHandle(user,{operation}),{status:403});for(const params of [{offset:-1},{offset:1.1},{status:'bad'}])await assert.rejects(s.core.adminHandle(admin,{operation:'listVouchers',...params}),{status:400});assert(!JSON.stringify(state.vouchers).includes('byuid'));assert(!JSON.stringify(state.vouchers).includes('nonce'));});

test('code deliveries expose only their private gift identifier and keep it stable on retries',async()=>{const s=setup();await s.core.adminHandle(admin,{operation:'addStock',code:'DIRECTGIFT1234',title:'Abrir direto',bucket:'shop'});await s.core.adminHandle(admin,{operation:'adjust',targetUid:'person',delta:1000,reason:'Teste',nonce:crypto.randomUUID()});const request={operation:'redeem',itemId:'code-default',nonce:crypto.randomUUID()},first=await s.core.handle(user,request),again=await s.core.handle(user,request);assert.match(first.giftId,/^codegift-/);assert.equal(first.giftId,again.giftId);assert(!JSON.stringify(first).includes('DIRECTGIFT1234'));const gift=await require('../code-gifts').openCodeGift(s.db,user,first.giftId,base);assert.equal(gift.gift.code,'DIRECTGIFT1234');await assert.rejects(require('../code-gifts').openCodeGift(s.db,{uid:'friend'},first.giftId,base),{status:404});assert.equal((await s.core.state(user)).wallet.balance,0);});

async function purchaseForReturn(s,{voucher=false,spin=false,price=1000,code='RETURNCODE1234'}={}){await s.core.adminHandle(admin,{operation:'addStock',code,title:'Prêmio devolvível',bucket:'both',imageUrl:'https://centralfreefire.com.br/item.webp',expiresAt:base+86400000});let response,request;if(spin){await seedLegacySpin(s);s.setTicket(.995);request={operation:'spin'};response=await s.core.handle(user,request);}else{if(voucher){const v=await issueVoucher(s);request={operation:'redeem',itemId:'code-default',payment:'voucher',voucherId:v.voucher.id,codeChoice:(await s.core.state(user)).shop[0].codeChoice,nonce:crypto.randomUUID()};}else{await s.core.adminHandle(admin,{operation:'saveItem',item:{id:'code-default',kind:'code',title:'Codiguinho',enabled:true,price}});await s.core.adminHandle(admin,{operation:'adjust',targetUid:'person',delta:price,reason:'Teste',nonce:crypto.randomUUID()});request={operation:'redeem',itemId:'code-default',nonce:crypto.randomUUID()};}response=await s.core.handle(user,request);}const receiptId=s.sql.exec('SELECT id FROM eco_receipts')[0].id;return {receiptId,giftId:response.giftId,request,body:{operation:'returnCode',receiptId,confirmUnused:true,bucket:'shop',reason:'Teste de resgate'}};}
test('an opened test code returns to shop with exactly the original coins and can be sold to someone else',async()=>{const s=setup(),p=await purchaseForReturn(s,{price:750});await require('../code-gifts').openCodeGift(s.db,user,p.giftId,base);const preview=await s.core.adminHandle(admin,{operation:'codeReturnPreview',targetUid:user.uid,giftId:p.giftId});assert.equal(preview.delivery.refundCoins,750);assert.equal(preview.delivery.canReturn,true);await s.core.adminHandle(admin,{operation:'saveItem',item:{id:'code-default',kind:'code',title:'Outro preço',price:1000,enabled:true}});const returned=await s.core.adminHandle(admin,p.body);assert.equal(returned.delivery.status,'returned');let state=await s.core.state(user);assert.deepEqual({...state.wallet},{balance:750,earned:750,spent:0});assert.equal(state.codeRedeemAvailableAt,0);assert.equal(state.codeStock.shop,1);assert.equal(state.codeStock.roulette,0);assert.equal(state.shop[0].imageUrl,'https://centralfreefire.com.br/item.webp');assert(!('code' in s.data['communityCodeGifts/person/'+p.giftId]));await assert.rejects(require('../code-gifts').openCodeGift(s.db,user,p.giftId,base),{status:410});await assert.rejects(s.core.handle(user,p.request),{status:409});await assert.rejects(s.core.handle(user,{operation:'retryDelivery',receiptId:p.receiptId}),{status:409});await s.core.adminHandle(admin,{operation:'adjust',targetUid:'friend',delta:1000,reason:'Teste',nonce:crypto.randomUUID()});const buyer=await s.core.handle({uid:'friend',provider:'google.com'},{operation:'redeem',itemId:'code-default',nonce:crypto.randomUUID()});assert.notEqual(buyer.giftId,p.giftId);assert.equal((await require('../code-gifts').openCodeGift(s.db,{uid:'friend'},buyer.giftId,base)).gift.code,'RETURNCODE1234');assert.equal((await s.core.adminHandle(admin,p.body)).duplicate,true);assert.equal((await s.core.state(user)).wallet.balance,750);});
test('voucher returns restore the same voucher with its original validity and never issue coins',async()=>{const s=setup(),p=await purchaseForReturn(s,{voucher:true}),id=p.request.voucherId;await s.core.adminHandle(admin,p.body);const state=await s.core.state(user);assert.equal(state.vouchers.next.id,id);assert.equal(state.vouchers.next.expiresAt,base+86400000);assert.equal(state.vouchers.availableCount,1);assert.equal(state.wallet.balance,0);assert.equal((await s.core.adminHandle(admin,{operation:'codeReturnPreview',receiptId:p.receiptId})).delivery.restoreVoucher,true);await s.core.handle(user,{...p.request,nonce:crypto.randomUUID()});assert.equal((await s.core.state(user)).vouchers.availableCount,0);});
test('a returned roulette prize does not grant coins or another free spin',async()=>{const s=setup(),p=await purchaseForReturn(s,{spin:true});await s.core.adminHandle(admin,p.body);assert.equal((await s.core.state(user)).wallet.balance,0);assert.equal((await s.core.state(user)).spin.result.id,'code');await assert.rejects(s.core.handle(user,{operation:'spin'}),{status:409});assert.equal(s.sql.exec('SELECT COUNT(*) AS n FROM eco_receipts')[0].n,1);});
test('only the real admin with an unused-code confirmation can return completed unexpired stock gifts',async()=>{const s=setup(),p=await purchaseForReturn(s);for(const op of ['codeDeliveries','codeReturnPreview','returnCode'])await assert.rejects(s.core.adminHandle(user,{...p.body,operation:op}),{status:403});await assert.rejects(s.core.adminHandle(admin,{...p.body,confirmUnused:false}),{status:400});await assert.rejects(s.core.adminHandle(admin,{...p.body,reason:''}),{status:400});await assert.rejects(s.core.adminHandle(admin,{...p.body,bucket:'manual'}),{status:400});await assert.rejects(s.core.adminHandle(admin,{operation:'codeReturnPreview',targetUid:'friend',giftId:p.giftId}),{status:404});assert.equal((await s.core.state(user)).codeStock.shop,0);s.setTime(base+86400000);await assert.rejects(s.core.adminHandle(admin,p.body),/expirou/);assert.equal(s.sql.exec('SELECT COUNT(*) AS n FROM eco_code_returns')[0].n,0);});
test('interrupted returns keep stock reserved until completion and retry only one refund',async()=>{const s=setup(),p=await purchaseForReturn(s),transact=s.db.transact;s.db.transact=async(path,fn)=>{if(path.startsWith('communityCodeGiftAssignments/'))throw Error('offline');return transact(path,fn);};await assert.rejects(s.core.adminHandle(admin,p.body),/offline/);assert.equal((await s.core.state(user)).codeStock.shop,0);assert.equal((await s.core.state(user)).wallet.balance,0);assert.equal((await s.core.adminHandle(admin,{operation:'codeDeliveries',status:'returning'})).total,1);await assert.rejects(s.core.handle(user,p.request),{status:409});await assert.rejects(s.core.adminHandle(admin,{...p.body,bucket:'both'}),{status:409});s.db.transact=transact;await Promise.all([s.core.adminHandle(admin,p.body),s.core.adminHandle(admin,p.body)]);assert.equal((await s.core.state(user)).wallet.balance,1000);assert.equal((await s.core.state(user)).wallet.spent,0);assert.equal((await s.core.state(user)).codeStock.shop,1);assert.equal(s.sql.exec("SELECT COUNT(*) AS n FROM eco_ledger WHERE kind='code_refund'")[0].n,1);assert.equal((await s.core.adminHandle(admin,{operation:'codeDeliveries',status:'returned'})).entries[0].refundCoins,1000);});
test('return reconciliation clears only the matching old gift and preserves history and stock metadata',async()=>{const s=setup(),p=await purchaseForReturn(s),hash=s.sql.exec('SELECT hash FROM eco_stock')[0].hash;await s.core.adminHandle(admin,p.body);const gifts=await require('../code-gifts').giftStatus(s.db,admin,[hash]);assert.equal(gifts.gifts[0].returned,true);assert.equal(gifts.gifts[0].giftId,p.giftId);assert.equal(gifts.gifts[0].bucket,'shop');assert(!JSON.stringify(gifts).includes('RETURNCODE1234'));E.initEconomy(s.sql);assert.equal((await s.core.adminHandle(admin,{operation:'codeDeliveries',status:'returned'})).total,1);for(const body of [{offset:-1},{offset:1.5},{status:'bad'}])await assert.rejects(s.core.adminHandle(admin,{operation:'codeDeliveries',...body}),{status:400});});
test('an older delivery still in flight cannot resurrect a returned gift or overwrite its new buyer',async()=>{const s=setup();await s.core.adminHandle(admin,{operation:'addStock',code:'RACERETURN1234',title:'Corrida',bucket:'shop'});for(const uid of ['person','friend'])await s.core.adminHandle(admin,{operation:'adjust',targetUid:uid,delta:1000,reason:'Teste',nonce:crypto.randomUUID()});const request={operation:'redeem',itemId:'code-default',nonce:crypto.randomUUID()},transact=s.db.transact;let calls=0,release;const held=new Promise(r=>release=r);s.db.transact=async(path,fn)=>{if(path.startsWith('communityCodeGifts/person/')&&++calls===2)await held;return transact(path,fn);};const one=s.core.handle(user,request),two=s.core.handle(user,request),settled=Promise.allSettled([one,two]);const first=await one;const id=s.sql.exec('SELECT id FROM eco_receipts WHERE uid=?','person')[0].id;await s.core.adminHandle(admin,{operation:'returnCode',receiptId:id,confirmUnused:true,bucket:'shop',reason:'Teste concorrente'});const buyer=await s.core.handle({uid:'friend',provider:'google.com'},{...request,nonce:crypto.randomUUID()});release();const results=await settled;assert.equal(results[1].status,'rejected');assert.equal((await require('../code-gifts').openCodeGift(s.db,{uid:'friend'},buyer.giftId,base)).gift.code,'RACERETURN1234');await assert.rejects(require('../code-gifts').openCodeGift(s.db,user,first.giftId,base),{status:410});assert.equal((await s.core.state(user)).wallet.balance,1000);assert.equal(s.sql.exec('SELECT status FROM eco_receipts WHERE id=?',id)[0].status,'returned');});

test('roulette vouchers work without stock, are private and are issued once for concurrent retries',async()=>{const s=setup();s.setTicket(.995);s.db.transact=async()=>{throw Error('Voucher spin must not write to Firebase');};s.db.update=s.db.transact;const [first,second]=await Promise.all([s.core.handle(user,{operation:'spin'}),s.core.handle(user,{operation:'spin'})]);assert.equal(first.result.id,'voucher');assert.equal(first.voucherId,second.voucherId);assert.equal(s.sql.exec('SELECT COUNT(*) AS n FROM eco_vouchers WHERE uid=?',user.uid)[0].n,1);assert.equal(s.sql.exec('SELECT COUNT(*) AS n FROM eco_receipts')[0].n,0);assert.equal(s.sql.exec('SELECT COUNT(*) AS n FROM user_inbox_messages')[0].n,1);const own=await s.core.state(user),other=await s.core.state({uid:'friend',provider:'google.com'});assert.equal(own.vouchers.next.source,'roulette');assert.equal(own.vouchers.next.id,first.voucherId);assert.equal(own.wallet.balance,0);assert.equal(other.vouchers.entries.length,0);assert.equal(other.vouchers.availableCount,0);assert(!JSON.stringify(other).includes(first.voucherId));assert.equal(first.result.expiresAt,Date.parse('2026-11-12T23:59:59.999-03:00'));});
test('voucher, daily result and notification roll back together if saving the spin fails',async()=>{const s=setup();s.setTicket(.995);const exec=s.sql.exec;s.sql.exec=(q,...args)=>{if(q.startsWith('UPDATE eco_daily SET spin='))throw Error('Disk unavailable');return exec(q,...args);};await assert.rejects(s.core.handle(user,{operation:'spin'}),/Disk unavailable/);assert.equal(exec('SELECT COUNT(*) AS n FROM eco_vouchers')[0].n,0);assert.equal(exec('SELECT COUNT(*) AS n FROM user_inbox_messages')[0].n,0);s.sql.exec=exec;await s.core.handle(user,{operation:'spin'});assert.equal(exec('SELECT COUNT(*) AS n FROM eco_vouchers')[0].n,1);assert.equal(exec('SELECT COUNT(*) AS n FROM user_inbox_messages')[0].n,1);});
test('roulette validity is admin-only, preserves artwork and changes only future awards',async()=>{const s=setup(),imageUrl='https://centralfreefire.com.br/edition/ticket.webp',chances=E.DEFAULT_CHANCES.map(p=>({...p}));await s.core.adminHandle(admin,{operation:'saveVoucherConfig',imageUrl});await s.core.adminHandle(admin,{operation:'saveChances',chances,voucherValidityDays:7});s.setTicket(.995);const first=await s.core.handle(user,{operation:'spin'});assert.equal(first.result.expiresAt,Date.parse('2026-10-20T23:59:59.999-03:00'));assert.equal(first.result.imageUrl,imageUrl);await s.core.adminHandle(admin,{operation:'saveVoucherConfig',imageUrl:'https://centralfreefire.com.br/edition/other.webp'});assert.equal((await s.core.adminHandle(admin,{operation:'dashboard'})).rouletteVoucher.validityDays,7);await s.core.adminHandle(admin,{operation:'saveChances',chances,voucherValidityDays:2});assert.equal((await s.core.handle(user,{operation:'spin'})).result.expiresAt,first.result.expiresAt);s.setTime(base+86400000);const next=await s.core.handle(user,{operation:'spin'});assert.notEqual(first.voucherId,next.voucherId);assert.equal(next.result.expiresAt,Date.parse('2026-10-16T23:59:59.999-03:00'));assert.equal((await s.core.state(user)).vouchers.entries.find(v=>v.id===first.voucherId).expiresAt,first.result.expiresAt);for(const days of [0,366,1.5,'7',null])await assert.rejects(s.core.adminHandle(admin,{operation:'saveChances',chances,voucherValidityDays:days}),{status:400});await assert.rejects(s.core.adminHandle(user,{operation:'saveChances',chances,voucherValidityDays:7}),{status:403});});
test('a won voucher redeems the chosen code even during the monthly coin cooldown',async()=>{const s=setup();for(const title of ['Primeiro','Escolhido'])await s.core.adminHandle(admin,{operation:'addStock',code:'CHOOSE'+title.toUpperCase(),title,bucket:'shop'});await s.core.adminHandle(admin,{operation:'adjust',targetUid:user.uid,delta:1000,reason:'Teste',nonce:crypto.randomUUID()});const first=(await s.core.state(user)).shop.find(p=>p.title==='Primeiro');await s.core.handle(user,{operation:'redeem',itemId:'code-default',codeChoice:first.codeChoice,nonce:crypto.randomUUID()});s.setTicket(.995);const won=await s.core.handle(user,{operation:'spin'}),before=await s.core.state(user),choice=before.shop.find(p=>p.title==='Escolhido');assert(before.codeRedeemAvailableAt>base);assert.equal(before.codeStock.shop,1);const request={operation:'redeem',itemId:'code-default',payment:'voucher',voucherId:won.voucherId,codeChoice:choice.codeChoice,nonce:crypto.randomUUID()},delivered=await s.core.handle(user,request);assert.equal(delivered.result.label,'Escolhido');assert.equal((await s.core.handle(user,request)).giftId,delivered.giftId);const after=await s.core.state(user);assert.equal(after.wallet.balance,0);assert.equal(after.wallet.spent,1000);assert.equal(after.vouchers.availableCount,0);assert.equal(after.vouchers.entries[0].status,'used');assert.equal(after.codeStock.shop,0);});
test('stock migration runs once, moves only unclaimed roulette codes and preserves legacy delivery receipts',async()=>{const s=setup();await s.core.adminHandle(admin,{operation:'addStock',code:'OLDPRIZE123',title:'Prêmio antigo',bucket:'roulette'});const legacy=await seedLegacySpin(s);await s.core.adminHandle(admin,{operation:'addStock',code:'FREESTOCK123',title:'Prêmio livre',bucket:'roulette'});s.sql.exec('DELETE FROM eco_settings WHERE id=?','roulette-vouchers-v1');E.initEconomy(s.sql);assert.equal(s.sql.exec('SELECT bucket FROM eco_stock WHERE receipt IS NULL')[0].bucket,'shop');assert.equal(s.sql.exec('SELECT bucket FROM eco_stock WHERE receipt=?',legacy.id)[0].bucket,'roulette');const exec=s.sql.exec,queries=[];s.sql.exec=(q,...args)=>{queries.push(q);return exec(q,...args);};E.initEconomy(s.sql);assert(!queries.some(q=>q.includes('UPDATE eco_stock SET bucket=')));const delivered=await s.core.handle(user,{operation:'spin'});assert.equal(delivered.result.id,'code');assert.equal(delivered.giftId,legacy.giftId);assert.equal((await s.core.state(user)).vouchers.availableCount,0);});

test('individual prize promotions use the real base price, keep other rewards unchanged and expose the earliest expiry without private codes',async()=>{
 const s=setup();for(const [code,title,days]of [['SALECODE111','Dino',2],['SALECODE222','Dino',5],['NORMALCODE111','Gato',8]])await s.core.adminHandle(admin,{operation:'addStock',code,title,bucket:'shop',expiresAt:base+days*86400000});
 await s.core.adminHandle(admin,{operation:'setCodePromotion',title:'Dino',salePrice:700});let state=await s.core.state(user),dino=state.shop.find(p=>p.title==='Dino'),gato=state.shop.find(p=>p.title==='Gato');assert.equal(dino.price,700);assert.equal(dino.originalPrice,1000);assert.equal(dino.quantity,2);assert.equal(dino.expiresAt,base+2*86400000);assert.equal(gato.price,1000);assert(!JSON.stringify(state.shop).includes('SALECODE'));
 await s.core.adminHandle(admin,{operation:'addStock',code:'SALECODE333',title:'Dino',bucket:'shop'});assert.equal((await s.core.state(user)).shop.find(p=>p.title==='Dino').price,700);
 await s.core.adminHandle(admin,{operation:'setCodePromotion',title:'Dino',salePrice:0});assert.equal((await s.core.state(user)).shop.find(p=>p.title==='Dino').price,1000);
});
test('server charges the promotion once, preserves the charged price on retry, returns that exact amount and keeps the cooldown',async()=>{
 const s=setup();for(const code of ['PROMOPAID111','PROMOPAID222'])await s.core.adminHandle(admin,{operation:'addStock',code,title:'Promo',bucket:'shop'});await s.core.adminHandle(admin,{operation:'setCodePromotion',title:'Promo',salePrice:600});await s.core.adminHandle(admin,{operation:'adjust',targetUid:'person',delta:1000,reason:'Teste',nonce:crypto.randomUUID()});
 const item=(await s.core.state(user)).shop[0],b={operation:'redeem',itemId:item.id,codeChoice:item.codeChoice,expectedPrice:600,expectedExpiresAt:0,nonce:crypto.randomUUID()};let result=await s.core.handle(user,b);assert.equal((await s.core.state(user)).wallet.balance,400);assert.equal(s.sql.exec('SELECT delta FROM eco_ledger WHERE kind=?','redeem')[0].delta,-600);
 await s.core.adminHandle(admin,{operation:'setCodePromotion',title:'Promo',salePrice:800});assert.equal((await s.core.handle(user,b)).giftId,result.giftId);assert.equal((await s.core.state(user)).wallet.balance,400);await assert.rejects(s.core.handle(user,{...b,expectedPrice:800,nonce:crypto.randomUUID()}),{status:400});
 await s.core.adminHandle(admin,{operation:'returnCode',giftId:result.giftId,targetUid:user.uid,confirmUnused:true,bucket:'shop',reason:'Teste sem uso'});assert.equal((await s.core.state(user)).wallet.balance,1000);assert.equal(s.sql.exec('SELECT delta FROM eco_ledger WHERE kind=?','code_refund')[0].delta,600);
});
test('stale, forged or changed price and validity never spend coins or consume a voucher',async()=>{
 const s=setup();await s.core.adminHandle(admin,{operation:'addStock',code:'STALESALE111',title:'Promo',bucket:'shop',expiresAt:base+86400000});await s.core.adminHandle(admin,{operation:'adjust',targetUid:'person',delta:1000,reason:'Teste',nonce:crypto.randomUUID()});const item=(await s.core.state(user)).shop[0];await s.core.adminHandle(admin,{operation:'setCodePromotion',title:'Promo',salePrice:500});
 const b={operation:'redeem',itemId:item.id,codeChoice:item.codeChoice,nonce:crypto.randomUUID()};for(const expectedPrice of [1000,1,-1,'500',500.5])await assert.rejects(s.core.handle(user,{...b,nonce:crypto.randomUUID(),expectedPrice}),{status:409});await assert.rejects(s.core.handle(user,{...b,expectedPrice:500,expectedExpiresAt:base+2*86400000}),{status:409});assert.equal((await s.core.state(user)).wallet.balance,1000);assert.equal(s.sql.exec('SELECT COUNT(*) AS n FROM eco_receipts')[0].n,0);
 s.setTicket(.995);const voucher=await s.core.handle(user,{operation:'spin'});s.setTime(base+2*86400000);await assert.rejects(s.core.handle(user,{...b,payment:'voucher',voucherId:voucher.voucherId,nonce:crypto.randomUUID()}),{status:409});assert.equal(s.sql.exec('SELECT receipt FROM eco_vouchers WHERE id=?',voucher.voucherId)[0].receipt,null);
});
test('voucher promotions cost one voucher and zero coins while legacy clients also receive the actual lower price',async()=>{
 const s=setup();for(const code of ['VALESALE111','VALESALE222'])await s.core.adminHandle(admin,{operation:'addStock',code,title:'Promo',bucket:'shop'});await s.core.adminHandle(admin,{operation:'setCodePromotion',title:'Promo',salePrice:450});s.setTicket(.995);const voucher=await s.core.handle(user,{operation:'spin'}),item=(await s.core.state(user)).shop[0];await s.core.handle(user,{operation:'redeem',itemId:item.id,codeChoice:item.codeChoice,payment:'voucher',voucherId:voucher.voucherId,expectedPrice:450,nonce:crypto.randomUUID()});assert.equal((await s.core.state(user)).wallet.balance,0);await s.core.adminHandle(admin,{operation:'adjust',targetUid:'person',delta:500,reason:'Teste',nonce:crypto.randomUUID()});await s.core.handle(user,{operation:'redeem',itemId:item.id,codeChoice:item.codeChoice,price:1,nonce:crypto.randomUUID()});assert.equal((await s.core.state(user)).wallet.balance,50);
});
test('only administrators can save real discounts, base price changes never fabricate savings, and existing stock survives initialization',async()=>{
 const s=setup();await s.core.adminHandle(admin,{operation:'addStock',code:'VALIDSALE111',title:'Promo',bucket:'shop'});await assert.rejects(s.core.adminHandle(user,{operation:'setCodePromotion',title:'Promo',salePrice:500}),{status:403});for(const price of [-1,1000,1001,'500',NaN,500.5])await assert.rejects(s.core.adminHandle(admin,{operation:'setCodePromotion',title:'Promo',salePrice:price}),{status:400});await assert.rejects(s.core.adminHandle(admin,{operation:'setCodePromotion',title:'Ausente',salePrice:500}),{status:409});await s.core.adminHandle(admin,{operation:'setCodePromotion',title:'Promo',salePrice:700});E.initEconomy(s.sql);assert.equal((await s.core.state(user)).shop[0].price,700);await s.core.adminHandle(admin,{operation:'saveItem',item:{id:'code-default',kind:'code',title:'Um código',price:600,enabled:true}});const item=(await s.core.state(user)).shop[0];assert.equal(item.price,600);assert.equal(item.originalPrice,600);const stock=(await s.core.adminHandle(admin,{operation:'dashboard'})).stock[0],status=await s.core.adminHandle(admin,{operation:'stockStatus',hashes:[stock.hash]});assert.equal(status.codePrice,600);assert.equal(status.stock[0].salePrice,700);
});
